{
  "items": [
    {
      "name": "Filter.Eventually.exists",
      "module_name": "Mathlib.Order.Filter.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u} {p : α → Prop} {f : Filter α} [f.NeBot], (∀ᶠ (x : α) in f, p x) → ∃ x, p x"
    },
    {
      "name": "Filter.Eventually.and",
      "module_name": "Mathlib.Order.Filter.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u} {p q : α → Prop} {f : Filter α},\n  Filter.Eventually p f → Filter.Eventually q f → ∀ᶠ (x : α) in f, p x ∧ q x"
    },
    {
      "name": "Filter.Eventually.exists_mem",
      "module_name": "Mathlib.Order.Filter.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u} {p : α → Prop} {f : Filter α}, (∀ᶠ (x : α) in f, p x) → ∃ v ∈ f, ∀ y ∈ v, p y"
    },
    {
      "name": "eventually_nhdsSet_iff_forall",
      "module_name": "Mathlib.Topology.NhdsSet",
      "kind": "theorem",
      "type": "∀ {X : Type u_1} [inst : TopologicalSpace X] {s : Set X} {p : X → Prop},\n  (∀ᶠ (x : X) in nhdsSet s, p x) ↔ ∀ x ∈ s, ∀ᶠ (y : X) in nhds x, p y"
    },
    {
      "name": "Filter.Frequently.and_eventually",
      "module_name": "Mathlib.Order.Filter.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u} {p q : α → Prop} {f : Filter α},\n  (∃ᶠ (x : α) in f, p x) → (∀ᶠ (x : α) in f, q x) → ∃ᶠ (x : α) in f, p x ∧ q x"
    },
    {
      "name": "Filter.eventually_and",
      "module_name": "Mathlib.Order.Filter.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u} {p q : α → Prop} {f : Filter α},\n  (∀ᶠ (x : α) in f, p x ∧ q x) ↔ (∀ᶠ (x : α) in f, p x) ∧ ∀ᶠ (x : α) in f, q x"
    }
  ]
}
